begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(29);
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)values
('00000000-0000-4000-8000-000000002901','authenticated','authenticated','s191product-a@veyocast.test','test',now(),now(),now(),'{}','{}'),
('00000000-0000-4000-8000-000000002902','authenticated','authenticated','s191product-b@veyocast.test','test',now(),now(),now(),'{}','{}'),
('00000000-0000-4000-8000-000000002903','authenticated','authenticated','s191product-viewer@veyocast.test','test',now(),now(),now(),'{}','{}');
insert into public.profiles(id,display_name)values('00000000-0000-4000-8000-000000002901','Product A'),('00000000-0000-4000-8000-000000002902','Product B'),('00000000-0000-4000-8000-000000002903','Viewer');
insert into public.tenants(id,name,slug)values('10000000-0000-4000-8000-000000002901','Products A','s191products-a'),('10000000-0000-4000-8000-000000002902','Products B','s191products-b');
insert into public.tenant_settings(tenant_id)values('10000000-0000-4000-8000-000000002901'),('10000000-0000-4000-8000-000000002902');
insert into public.tenant_memberships(tenant_id,user_id,role)values('10000000-0000-4000-8000-000000002901','00000000-0000-4000-8000-000000002901','tenant_owner'),('10000000-0000-4000-8000-000000002902','00000000-0000-4000-8000-000000002902','tenant_owner'),('10000000-0000-4000-8000-000000002901','00000000-0000-4000-8000-000000002903','tenant_viewer');
insert into public.dynamic_data_sources(id,tenant_id,kind,name,status)values('20000000-0000-4000-8000-000000002901','10000000-0000-4000-8000-000000002901','manual_products','Own manual','active'),('20000000-0000-4000-8000-000000002902','10000000-0000-4000-8000-000000002902','manual_products','Other manual','active'),('20000000-0000-4000-8000-000000002903','10000000-0000-4000-8000-000000002901','twelve_excel','Provider products','active');
insert into public.tenant_products(id,tenant_id,data_source_id,source,source_external_id,slug,name,price_cents,currency,active,available,revision,custom_fields)values('30000000-0000-4000-8000-000000002903','10000000-0000-4000-8000-000000002901','20000000-0000-4000-8000-000000002903','twelve_excel','PROVIDER-42','provider-product','Imported product',425,'EUR',true,true,7,'{"providerField":"preserved"}');
select set_config('test.s191product_values','{"name":"Club product","description":"Actual catalog","category":"Dranken","priceCents":235,"vatRate":9,"unit":"glas","barcode":null,"externalId":"ART-001","active":true}',true);
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000002901',true);
select set_config('test.s191product_result',public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',null,'20000000-0000-4000-8000-000000002901',0,'create',current_setting('test.s191product_values')::jsonb,'50000000-0000-4000-8000-000000002901')::text,true);
select is(current_setting('test.s191product_result')::jsonb->>'outcome','created','real create saves the product');
select set_config('test.s191product_id',current_setting('test.s191product_result')::jsonb->>'productId',true);
select is((select price_cents from public.tenant_products where id=current_setting('test.s191product_id')::uuid),235,'save and reload retains exact integer cents');
select is((select source from public.tenant_products where id=current_setting('test.s191product_id')::uuid),'manual','new products preserve manual provenance');
select is(public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',null,'20000000-0000-4000-8000-000000002901',0,'create',current_setting('test.s191product_values')::jsonb,'50000000-0000-4000-8000-000000002901'),current_setting('test.s191product_result')::jsonb,'idempotent retry returns exact result');
select is((select count(*)from public.tenant_products where tenant_id='10000000-0000-4000-8000-000000002901'and source_external_id='ART-001'),1::bigint,'retry does not create another catalog row');
select set_config('test.s191product_slide',public.create_dynamic_slide_v1('10000000-0000-4000-8000-000000002901','Frozen product menu',(select current_published_version_id from public.dynamic_templates where slide_type='price_list'and status='published'and orientation='landscape'limit 1), '20000000-0000-4000-8000-000000002901','latest',jsonb_build_object('schemaVersion',1,'title','Frozen menu','slidePhotoMode','hide','sections',jsonb_build_array(jsonb_build_object('id','60000000-0000-4000-8000-000000002901','categoryId','Dranken','column','left','photoMode','inherit','order',0,'products',jsonb_build_array(jsonb_build_object('id','60000000-0000-4000-8000-000000002902','productId',current_setting('test.s191product_id'),'visible',true,'order',0))))))::text,true);
select set_config('test.s191product_snapshot',(select snapshot_data_json::text from public.dynamic_slide_snapshots where id=(current_setting('test.s191product_slide')::jsonb->>'snapshotId')::uuid),true);
select ok(position('235'in current_setting('test.s191product_snapshot'))>0,'real generated snapshot stores original product price');
select throws_ok($$select public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',null,'20000000-0000-4000-8000-000000002901',0,'create',jsonb_set(current_setting('test.s191product_values')::jsonb,'{priceCents}','236'),'50000000-0000-4000-8000-000000002901')$$,'23505',null,'changed values cannot reuse a completed command');
select throws_ok($$select public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',null,'20000000-0000-4000-8000-000000002902',0,'create',current_setting('test.s191product_values')::jsonb,'50000000-0000-4000-8000-000000002902')$$,'23514',null,'cross-tenant product source is rejected');
select throws_ok($$select public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',null,'20000000-0000-4000-8000-000000002903',0,'create',current_setting('test.s191product_values')::jsonb,'50000000-0000-4000-8000-000000002902')$$,'23514',null,'manual create cannot pretend to originate from Twelve');
select throws_ok($$select public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',null,'20000000-0000-4000-8000-000000002901',0,'create',jsonb_set(current_setting('test.s191product_values')::jsonb,'{priceCents}','2.35'),'50000000-0000-4000-8000-000000002902')$$,'23514',null,'fractional minor-unit prices are rejected');
select throws_ok($$select public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',null,'20000000-0000-4000-8000-000000002901',0,'create',current_setting('test.s191product_values')::jsonb||'{"tenantId":"10000000-0000-4000-8000-000000002902"}','50000000-0000-4000-8000-000000002902')$$,'23514',null,'browser cannot inject tenant or provenance fields');
select throws_ok($$select public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',null,'20000000-0000-4000-8000-000000002901',0,'create',jsonb_set(current_setting('test.s191product_values')::jsonb,'{externalId}','"art-001"'),'50000000-0000-4000-8000-000000002902')$$,'23505',null,'article number uniqueness is normalized within the source');
select set_config('test.s191product_update',public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',current_setting('test.s191product_id')::uuid,null,1,'update',jsonb_set(jsonb_set(current_setting('test.s191product_values')::jsonb,'{externalId}','"ART-002"'),'{priceCents}','249'),'50000000-0000-4000-8000-000000002904')::text,true);
select is(current_setting('test.s191product_update')::jsonb->>'outcome','updated','real update confirms save');
select is((select source_external_id from public.tenant_products where id=current_setting('test.s191product_id')::uuid),'ART-002','article number is persisted and reloaded');
select is((public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',current_setting('test.s191product_id')::uuid,null,1,'update',current_setting('test.s191product_values')::jsonb,'50000000-0000-4000-8000-000000002905')->>'outcome'),'conflict','stale update fails with a CAS conflict');
select is((select price_cents from public.tenant_products where id=current_setting('test.s191product_id')::uuid),249,'stale update retains the last confirmed price');
select is((public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901','30000000-0000-4000-8000-000000002903',null,7,'update',jsonb_set(current_setting('test.s191product_values')::jsonb,'{externalId}','"PROVIDER-43"'),'50000000-0000-4000-8000-000000002906')->>'outcome'),'updated','provider-origin product permits an explicit article correction');
select is((select source from public.tenant_products where id='30000000-0000-4000-8000-000000002903'),'twelve_excel','editing never changes provider provenance');
select is((select custom_fields from public.tenant_products where id='30000000-0000-4000-8000-000000002903'),' {"providerField":"preserved"}'::jsonb,'provider metadata stays intact');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000002902',true);
select is((select count(*)from public.tenant_products where tenant_id='10000000-0000-4000-8000-000000002901'),0::bigint,'tenant B cannot read tenant A products');
select throws_ok($$select public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002902',current_setting('test.s191product_id')::uuid,null,2,'delete','{}','50000000-0000-4000-8000-000000002907')$$,'42501',null,'tenant B cannot remove a product by guessing its ID');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000002903',true);
select throws_ok($$select public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',current_setting('test.s191product_id')::uuid,null,2,'delete','{}','50000000-0000-4000-8000-000000002907')$$,'42501',null,'read-only users cannot mutate products');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000002901',true);
reset role;
insert into public.tenant_memberships(tenant_id,user_id,role)values('10000000-0000-4000-8000-000000002902','00000000-0000-4000-8000-000000002901','tenant_owner');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000002901',true);
select set_config('test.s191product_other',public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002902',null,'20000000-0000-4000-8000-000000002902',0,'create',current_setting('test.s191product_values')::jsonb,'50000000-0000-4000-8000-000000002901')::text,true);
select isnt(current_setting('test.s191product_other')::jsonb->>'productId',current_setting('test.s191product_id'),'same actor and idempotency key remain independent between two authorized tenants');
select is((select tenant_id from public.tenant_products where id=(current_setting('test.s191product_other')::jsonb->>'productId')::uuid),'10000000-0000-4000-8000-000000002902'::uuid,'second-tenant command binds the real product to the selected tenant');
select set_config('test.s191product_delete',public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',current_setting('test.s191product_id')::uuid,null,2,'delete','{}','50000000-0000-4000-8000-000000002908')::text,true);
select is(current_setting('test.s191product_delete')::jsonb->>'outcome','archived','removal confirms preserved catalog identity');
select ok((select deleted_at is not null and not active and not available and price_cents=249 and source_external_id='ART-002'from public.tenant_products where id=current_setting('test.s191product_id')::uuid),'removal hides the product but preserves immutable fallback identity and exact price');
select is((select snapshot_data_json from public.dynamic_slide_snapshots where id=(current_setting('test.s191product_slide')::jsonb->>'snapshotId')::uuid),current_setting('test.s191product_snapshot')::jsonb,'actual immutable menu snapshot remains unchanged after price edits and removal');
select is(public.manage_tenant_product_v2('10000000-0000-4000-8000-000000002901',current_setting('test.s191product_id')::uuid,null,2,'delete','{}','50000000-0000-4000-8000-000000002908'),current_setting('test.s191product_delete')::jsonb,'retry of removal causes no extra revision');
select ok(not has_function_privilege('anon','public.manage_tenant_product_v2(uuid,uuid,uuid,bigint,text,jsonb,uuid)','execute')and not has_function_privilege('service_role','public.manage_tenant_product_v2(uuid,uuid,uuid,bigint,text,jsonb,uuid)','execute'),'only authenticated guarded commands are callable');
select *from finish();
rollback;
